shader:
// Liquid Morph v4 (0.4 s) - A is stirred away through a curl-noise flow like paint in water while B surges up from below
// behind a curling ink front; speed, displacement and blur peak at the hidden cut. Same look as v2 (0.8 s) at half the
// duration. Measured against v2 on the bench clips (9:16, default sliders): the whole visible change takes ~1.9x less
// time, the ink sweep (B from 10 to 90 % of the frame) is ~1.65x faster (148 vs 244 ms) and its peak speed ~1.5x. A full
// 2x on the sweep itself would need ~30 % of the frame per frame at 30 fps, which reads as a jump; a timing that stays
// smooth at every slider corner bottoms out at ~4 frames for 10 -> 90 %.
// * Image flow = curl noise + upward drift, speed range compressed (no stalled, still-sharp patches at the cut). Each
//   layer's sample path fades its normal component only where it would pull content IN from outside the frame, so the
//   mirror-wrapped samples never show cloned faces; outflow stays free, so nothing is squashed against an edge, and the
//   blocked sideways speed at the side walls turns vertical (no frozen strip).
// * Ink front = a height field along the sweep direction (noise varies along the front only, so the covered area grows
//   linearly with the sweep: no lumps, no stranded islands), stirred into curls and drips by a domain warp of the same
//   curl field, soft-clamped (C1) into a known range. The warp length stops growing at Flow size x Turbulence = 1.35, so
//   the big-flow corners no longer pile the top of the field up against the clamp (that band used to vanish in one
//   frame). The feather is measured in screen space (dFdx/dFdy), so it stays a thin wet edge, not a double exposure.
// * Sweep timing (lmEaseInOut): monotone C1 Hermite through 10 knots (PCHIP slopes), fitted on GPU-simulated composites
//   of 20 slider / aspect corners (Flow size and Turbulence at 0.7 / 1.5 alone and paired, Edge 0.1 / 0.8, 9:16, 16:9,
//   1:1) and checked on real renders: one surge into the cut, then a decelerating finish at every corner, so the last
//   band of A thins out instead of popping; the AB frame-to-frame change never rises again after its peak by more than
//   ~1 level (v3: up to +9.4). Default: B gains 3-9-14-20-26-19-9-1 % of the frame per frame, peak on the cut at ~2x the
//   average like v2 (v3 was a flat 9-14-18-19-19-15-7, an even wipe).
// * Displacement: A accelerates away (C q^2.5), B decelerates into place (C (1-q)^2.5); C grows with the flow size.
// * Motion blur: 24 jittered, tent-weighted sub-frame taps per layer along the curved path (flow re-evaluated every 4
//   taps). The shutter spans ~1.1 frame intervals at 0.4 s / 30 fps (~400 deg, the same ratio as the 0.8 s version), so
//   each frame's streak meets the next one (no strobing copies). The ink front gets 30 % of that shutter (a crisp wet
//   edge, no dissolve band) where it moves slowly, and 55 % over its fast stretch (progress ~0.3-0.55, back to 30 % by
//   0.78): in every moving frame the edge now advances 2.0-3.2x its own blur width instead of up to 4.4x, so it reads as
//   motion blur, not stepping. Plus a small golden-spiral defocus at the cut where the flow is slow.
// Cost: <= 48 texture taps per pixel (both layers only inside the front band), 48 gradient-noise calls.

const int LM_STEPS = 4;   // coarse path steps up to the blur window
const int LM_SEGS = 6;    // flow evaluations inside the blur window
const int LM_SEG = 4;     // taps per flow evaluation (24 taps per layer, 48 texture taps max)
const vec2 LM_DIR = vec2(0.2425, 0.9701);   // drift / sweep direction (up, slight tilt)
const float LM_DRIFT = 0.45;   // uniform drift share of the image flow
const float LM_REFR = 0.05;    // refraction offset at the ink edge
const float LM_SHEEN = 0.12;   // faint wet highlight on the edge
const float LM_WALL = 0.15;    // top / bottom band where inflow from outside the frame fades out
const float LM_WALLX = 0.08;   // left / right band (aspect units)
const float LM_HW = 0.05;      // half shutter window at the peak (progress units; ~1.1 frames at 0.4 s / 30 fps)
const float LM_VK = 0.5;       // speed-range compression of the image flow (0 = raw curl speeds)
const float LM_FB = 0.3;       // share of that shutter applied to the ink front (a crisp edge, no dissolve band)
const float LM_DEF = 0.008;    // defocus radius at the cut where the flow is slow (buries still-sharp patches)
const float MW_ADV = 0.25;    // domain-warp length of the ink front
const float MW_F = 2.3;      // finger frequency along the front
const float MW_N = 0.4;      // finger amplitude
const float MW_LO = 0.25;     // soft-clamp margin of the front field

vec2 lmHash(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973));
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.xx + p3.yz) * p3.zy);
}

// gradient noise with analytic derivatives: x = value, yz = d/dp
vec3 lmNoised(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
  vec2 du = 30.0 * f * f * (f * (f - 2.0) + 1.0);
  vec2 ga = lmHash(i) * 2.0 - 1.0;
  vec2 gb = lmHash(i + vec2(1.0, 0.0)) * 2.0 - 1.0;
  vec2 gc = lmHash(i + vec2(0.0, 1.0)) * 2.0 - 1.0;
  vec2 gd = lmHash(i + vec2(1.0, 1.0)) * 2.0 - 1.0;
  float va = dot(ga, f);
  float vb = dot(gb, f - vec2(1.0, 0.0));
  float vc = dot(gc, f - vec2(0.0, 1.0));
  float vd = dot(gd, f - vec2(1.0, 1.0));
  float k = va - vb - vc + vd;
  return vec3(va + u.x * (vb - va) + u.y * (vc - va) + u.x * u.y * k,
              ga + u.x * (gb - ga) + u.y * (gc - ga) + u.x * u.y * (ga - gb - gc + gd)
                 + du * (u.yx * k + vec2(vb, vc) - va));
}

// divergence-free curl of a 2-octave potential (aspect space, height = 1)
vec2 lmCurl(vec2 P, float q) {
  vec2 sp = P * (1.35 / scale) + vec2(0.2 * q, -0.6 * q);
  vec3 n0 = lmNoised(sp);
  mat2 rot = mat2(0.8, 0.6, -0.6, 0.8);
  vec3 n1 = lmNoised(rot * sp * 2.03 + vec2(17.3, 9.1));
  vec2 g = n0.yz + 0.3 * (transpose(rot) * n1.yz);
  return vec2(g.y, -g.x) * 1.1;
}

// trace velocity of a layer (dir = -1 for A, which traces upstream; +1 for B, which traces downstream) through the
// image flow = curl + drift. Wherever the trace would leave the frame (content flowing IN from outside) its normal
// component fades out near that edge, so no mirrored clone is ever pulled in; outflow stays free, so nothing piles up
// or gets squashed against an edge.
vec2 lmTrace(vec2 P, float q, float dir) {
  vec2 v = lmCurl(P, q) + LM_DIR * LM_DRIFT;
  v *= pow(1.0 / (length(v) + 0.25), LM_VK);   // compress the speed range: no stalled, still-sharp patches at the cut
  vec2 t = v * dir;
  // side walls: the blocked sideways speed turns into the layer's own vertical direction (no stalled strip)
  float rx = t.x < 0.0 ? smoothstep(0.0, LM_WALLX, P.x) : smoothstep(0.0, LM_WALLX, ratio - P.x);
  t = vec2(t.x * rx, t.y + 0.6 * abs(t.x) * (1.0 - rx) * t.y / (abs(t.y) + 0.15));
  t.y *= t.y < 0.0 ? smoothstep(0.0, LM_WALL, P.y) : smoothstep(0.0, LM_WALL, 1.0 - P.y);
  return t;
}

// front sweep timing: monotone C1 cubic Hermite through fitted knots (PCHIP slopes), exactly 0 at 0 and 1 at 1 (see the
// header). It surges into the cut and decelerates through the top of the field, whatever shape the sliders give it.
float lmHerm(float x, float x0, float x1, float y0, float y1, float s0, float s1) {
  float h = x1 - x0;
  float t = (x - x0) / h;
  float t2 = t * t;
  float t3 = t2 * t;
  return (2.0 * t3 - 3.0 * t2 + 1.0) * y0 + (t3 - 2.0 * t2 + t) * h * s0
       + (3.0 * t2 - 2.0 * t3) * y1 + (t3 - t2) * h * s1;
}
float lmEaseInOut(float x) {
  if (x < 0.150) return lmHerm(x, 0.000, 0.150, 0.000, 0.138, 0.944, 0.898);
  if (x < 0.250) return lmHerm(x, 0.150, 0.250, 0.138, 0.226, 0.898, 1.059);
  if (x < 0.350) return lmHerm(x, 0.250, 0.350, 0.226, 0.359, 1.059, 1.278);
  if (x < 0.450) return lmHerm(x, 0.350, 0.450, 0.359, 0.482, 1.278, 1.172);
  if (x < 0.550) return lmHerm(x, 0.450, 0.550, 0.482, 0.594, 1.172, 1.010);
  if (x < 0.650) return lmHerm(x, 0.550, 0.650, 0.594, 0.686, 1.010, 0.873);
  if (x < 0.750) return lmHerm(x, 0.650, 0.750, 0.686, 0.769, 0.873, 0.843);
  if (x < 0.870) return lmHerm(x, 0.750, 0.870, 0.769, 0.872, 0.843, 0.916);
  return lmHerm(x, 0.870, 1.000, 0.872, 1.000, 0.916, 1.050);
}
// displacement envelopes: A accelerates away (ease-in), B decelerates into place (ease-out)
float lmSA(float q, float C) { return C * q * q * sqrt(q); }
float lmSB(float q, float C) { float r = 1.0 - q; return C * r * r * sqrt(r); }

vec4 transition(vec2 uv) {
  float q = clamp(progress, 0.0, 1.0);
  vec2 asp = vec2(ratio, 1.0);
  vec2 P = uv * asp;
  float C = 0.6 * turbulence * scale;   // path length at the cut = 0.177 C; larger flows travel further
  float w = 0.045 * edge;              // front half-width in screen space (height = 1)

  // ---- ink front
  float maxDot = dot(asp, LM_DIR);
  vec2 Xm = P;
  float sm = MW_ADV * min(turbulence * scale, 1.35) * (0.4 + 0.6 * q);   // capped: no pile-up at the clamp
  for (int k = 0; k < 3; k++) Xm -= lmCurl(Xm, q) * (sm / 3.0);
  vec2 Dp = vec2(LM_DIR.y, -LM_DIR.x);
  float fm = MW_F / scale;
  float a = dot(Xm, LM_DIR);
  float u = dot(Xm, Dp) * fm;
  vec3 m1 = lmNoised(vec2(u + 3.7, 0.5));
  vec3 m2 = lmNoised(vec2(u * 2.13 + 5.2, 1.3));
  float amp = MW_N * (0.5 + 0.5 * q);   // fingers grow as the liquid pushes in
  float mr = (a + amp * (m1.x + 0.5 * m2.x)) / maxDot;
  // soft clamp into [-MW_LO, 1 + MW_LO] (C1 at 0 and 1: no plateau, so no lump in the coverage)
  float m = mr < 0.0 ? -MW_LO * (1.0 - exp(mr / MW_LO))
          : (mr > 1.0 ? 1.0 + MW_LO * (1.0 - exp((1.0 - mr) / MW_LO)) : mr);
  // smooth (approximate) front normal for the refraction / sheen direction, ignoring the warp's Jacobian
  vec2 gm = (LM_DIR + Dp * (amp * fm * (m1.y + 1.065 * m2.y))) / maxDot;
  vec2 gdir = gm / (length(gm) + 0.6);
  // constant on-screen feather from the true screen-space gradient (warp included)
  float ee = w * clamp(length(vec2(dFdx(m), dFdy(m))) * resolution.y, 0.4, 2.5);

  // ---- motion-blur window (progress units); collapses at both ends so p=0 / p=1 are exact
  float hw = LM_HW * smoothstep(0.0, 0.1, q) * (1.0 - smoothstep(0.9, 1.0, q));
  vec2 jj = lmHash(gl_FragCoord.xy + vec2(floor(q * 200.0) * 7.31, 0.0));
  float jit = jj.x;
  // defocus disc (golden-angle spiral, rotated per pixel), strongest at the cut
  float dq = (q - 0.5) / 0.13;
  float def = LM_DEF * exp(-dq * dq) * smoothstep(0.0, 0.1, q) * (1.0 - smoothstep(0.9, 1.0, q));
  vec2 d0 = vec2(cos(6.2832 * jj.y), sin(6.2832 * jj.y));
  const mat2 GOLD = mat2(-0.7374, 0.6755, -0.6755, -0.7374);

  float fb = LM_FB + 0.25 * smoothstep(0.12, 0.32, q) * (1.0 - smoothstep(0.55, 0.78, q));   // 30 -> 55 % when fast
  float lo = -MW_LO - 2.5 * w - 0.01;
  float hi = 1.0 + MW_LO + 2.5 * w + 0.01;
  const int NT = LM_SEGS * LM_SEG;
  float fT = float(NT);
  float q0 = clamp(q - hw + 2.0 * hw * jit / fT, 0.0, 1.0);
  float qN = clamp(q - hw + 2.0 * hw * (fT - 1.0 + jit) / fT, 0.0, 1.0);
  float mB0 = smoothstep(-ee, ee, mix(lo, hi, lmEaseInOut(q + (q0 - q) * fb)) - m);
  float mBN = smoothstep(-ee, ee, mix(lo, hi, lmEaseInOut(q + (qN - q) * fb)) - m);
  float refr = LM_REFR * turbulence;

  float wsum = 0.0;
  float rimAcc = 0.0;
  for (int j = 0; j < NT; j++) {
    float t = (float(j) + jit) / fT;
    float wt = 1.0 - 0.5 * abs(2.0 * t - 1.0);   // tent shutter
    float qj = clamp(q - hw + 2.0 * hw * t, 0.0, 1.0);
    float mb = smoothstep(-ee, ee, mix(lo, hi, lmEaseInOut(q + (qj - q) * fb)) - m);
    wsum += wt;
    rimAcc += wt * 4.0 * mb * (1.0 - mb);
  }

  vec3 acc = vec3(0.0);
  // ---- layer A: trace upstream (its content flows downstream, accelerating)
  if (mB0 < 1.0) {
    vec2 X = P;
    float sPrev = lmSA(q0, C);
    for (int k = 0; k < LM_STEPS; k++) X += lmTrace(X, q, -1.0) * (sPrev / float(LM_STEPS));
    vec2 dk = d0;
    for (int s = 0; s < LM_SEGS; s++) {
      vec2 v = lmTrace(X, q, -1.0);
      float dr = def * (0.3 + 0.7 * (1.0 - smoothstep(0.1, 0.6, length(v))));
      for (int k = 0; k < LM_SEG; k++) {
        float t = (float(s * LM_SEG + k) + jit) / fT;
        float qj = clamp(q - hw + 2.0 * hw * t, 0.0, 1.0);
        float sj = lmSA(qj, C);
        X += v * (sj - sPrev);
        sPrev = sj;
        float mb = smoothstep(-ee, ee, mix(lo, hi, lmEaseInOut(q + (qj - q) * fb)) - m);
        float rim = 4.0 * mb * (1.0 - mb);
        dk = GOLD * dk;
        vec2 off = dk * (dr * sqrt((float(s * LM_SEG + k) + 0.5) / fT));
        acc += getA((X + off - gdir * rim * refr) / asp).rgb * ((1.0 - mb) * (1.0 - 0.5 * abs(2.0 * t - 1.0)));
      }
    }
  }

  // ---- layer B: trace downstream (its content arrives from upstream, decelerating)
  if (mBN > 0.0) {
    vec2 X = P;
    float sPrev = lmSB(qN, C);
    for (int k = 0; k < LM_STEPS; k++) X += lmTrace(X, q, 1.0) * (sPrev / float(LM_STEPS));
    vec2 dk = d0;
    for (int s = 0; s < LM_SEGS; s++) {
      vec2 v = lmTrace(X, q, 1.0);
      float dr = def * (0.3 + 0.7 * (1.0 - smoothstep(0.1, 0.6, length(v))));
      for (int k = 0; k < LM_SEG; k++) {
        float t = (float(NT - 1 - (s * LM_SEG + k)) + jit) / fT;
        float qj = clamp(q - hw + 2.0 * hw * t, 0.0, 1.0);
        float sj = lmSB(qj, C);
        X += v * (sj - sPrev);
        sPrev = sj;
        float mb = smoothstep(-ee, ee, mix(lo, hi, lmEaseInOut(q + (qj - q) * fb)) - m);
        float rim = 4.0 * mb * (1.0 - mb);
        dk = GOLD * dk;
        vec2 off = dk * (dr * sqrt((float(s * LM_SEG + k) + 0.5) / fT));
        acc += getB((X + off + gdir * rim * refr) / asp).rgb * (mb * (1.0 - 0.5 * abs(2.0 * t - 1.0)));
      }
    }
  }

  vec3 col = acc / wsum;
  float rimv = rimAcc / wsum;
  float lit = clamp(dot(gdir, vec2(-0.6, 0.8)) * 1.4, 0.0, 1.0);
  col += LM_SHEEN * rimv * rimv * rimv * lit * (1.0 - col);
  return vec4(col, 1.0);
}
